This paper is concerned with the $0/1$-loss optimization:
\begin{equation}\label{ell-0-1}
\underset{\bfx\in\R^n}{\min}~ f(\bfx)+\lambda \|( A\bfx +\bfb )_+\|_0, 
\end{equation}

where $f:\R^n\rightarrow\R$ is  twice continuously differentiable, 
$\lambda>0 $ is a penalty parameter and $A\in \R^{m\times n}, \bfb\in \R^m$. 
Moreover, ${\bfz}_+:=((z_1)_+, \ldots, (z_m)_+)^\top $ with $z_+:=\max\{z,{0}\}$ 
and $\|\bfz\|_0$ is the $\ell_0$ norm of $\bfz$, counting the number of its non-zero entries. 
Hence, $\|\bfz_+\|_0$ counts the number of positive entries of $\bfz$,
i.e., $\|\bfz_+\|_0=\sum_{i=1}^m \ell_{0/1}(z_i)$, where
\begin{eqnarray*}
\ell_{0/1}(z)=
\begin{cases}
1, &z>0,\\
0& z\leq 0.
\end{cases}
\end{eqnarray*}

Given a subset $T\subseteq\N_m:=\{1,2,\ldots,m\}$, its cardinality and complementary set are $|T|$ and $\overline T$.   The neighbourhood of $\bfx\in\R^n$ with a radius $\delta>0$  is denoted by $N( \bfx,\delta)=\{\bfv\in\R^n: \|\bfv- \bfx \|< \delta\}$. 
Moreover, $\bfx_{T}$ (resp. $A_{T}$) represents the sub-vector (resp. sub-matrix) contains elements (resp. rows) of $\bfx$ indexed on $T$.   Particularly, $A_i$ is the $i$th row of $A$. 
We combine two vectors as $(\bfx;\bfy):=(\bfx^\top~\bfy^\top)^\top$. The $i$th   largest singular value of $H\in\R^{n\times n}$ is written $\sigma_{i}(H)$, namely $\sigma_{1}(H)\geq\sigma_{2}(H)\geq\cdots\geq\sigma_{n}(H).$
Particularly, we write $\|H\|:=\sigma_{1}(H)$ and $\sigma_{\min}(H):=\sigma_{n}(H).$ Finally, let $I$ be the identity matrix and $\bfe$ be the vector with all entries being ones. 


Next we describe the formula for computing the subdifferential of 
$\|\bfz_+\|_0$ and its proximal operator.
We note that $\|\cdot\|_0$ is lower semi-continuous (lsc)
and $\bfz_+$ is obviously continuous, 
the composition $\|\bfz_+\|_0$ is also lsc.
For a proper and lsc function $g: \R^m \mapsto \R$, its
subdifferential $\partial g(\cdot)$ is well defined as in \cite[Definition 8.3]{RW1998}. 


The assumption in (\ref{chain-rule-cond}) can be regarded as a constraint qualification for the chain rule in (\ref{chain-rule-sub}) to hold. We finish this section with a formula to compute the proximal operator of  $\|(\cdot)_+\|_0$.  Let $\alpha>0$, the proximal operator of $\alpha \|(\cdot)_+\|_0$ at  {$\bfo$ is defined by 
\begin{eqnarray*} %\label{proximal-operator-0}
\prox(\bfo)=\underset{\bfy\in\R^m}{\rm argmin} ~\frac{1}{2}\|\bfy-\bfo\|^2+ \alpha \|\bfy_+\|_0.
\end{eqnarray*}

As shown in \cite[Lemma 2.2]{wang2019support}, the proximal operator admits a closed form as


\begin{eqnarray} \label{proximal-operator}
\Big[\prox(\bfo)\Big]_i=
%&=&
%\begin{cases}
%0,&    \nu_i \in [0, \sqrt{2\alpha}),\\
%0~ \text{or}~ \nu_i ,& \nu_i=\sqrt{2\alpha},\\
%\nu_i,&\nu_i\in(-\infty,0)\cup (\sqrt{2\alpha},\infty),
%\end{cases} \nonumber\\
%&=&
\begin{cases}
0,&    \nu_i \in (0, \sqrt{2\alpha}),\\
0~ \text{or}~ \nu_i ,& \nu_i\in\{0,\sqrt{2\alpha}\},\\
\nu_i,&\nu_i\in(-\infty,0)\cup (\sqrt{2\alpha},\infty).
\end{cases} 
\end{eqnarray}

\begin{eqnarray}\label{T-*}
  \Gamma_*&:=&\{i\in\N_m: A_i\bfx^*+b_i=0\}.
\end{eqnarray}

\begin{definition}\label{def-p-sta} 
	A point $\bfx^*$ is called a P-stationary point of the problem (\ref{ell-0-1})  if there exist a constant $\tau > 0$ and
	a point $\bfz^*\in\R^m$  such that
\begin{eqnarray} \label{p-stationary}
 \begin{cases}
\hspace{21mm}\nabla f(\bfx^*)  + A^\top \bfz^* &=~ 0 \\
\pro (A\bfx^*+\bfb+\tau \bfz^*) &\ni~A\bfx^*+\bfb.
\end{cases}
\end{eqnarray}
\end{definition}

We also say a point $(\bfx^*;\bfz^*)$ is a P-stationary point of the problem (\ref{ell-0-1}) if it satisfies the conditions in \eqref{p-stationary}. 
For a point $\bfx^*$, we denote two constants by 


\begin{eqnarray}
\label{tau-*} 
~~~~\tau_1 := 
\begin{cases}
+\infty, & \bfy^*\leq0,\\
{\min} \left\{\frac{(y^*_i)^2}{2\lambda}:y_i^*>0\right\},& {\rm otherwise},\\
\end{cases}~~
\tau_2:=\begin{cases}
+\infty, & \Gamma_*=\emptyset,\\
 \frac{2\lambda}{\max_i|p^*_i|^2},& {\rm otherwise},
\end{cases}
\end{eqnarray}

where $\bfy^*:=A\bfx^*+\bfb$ and $\bfp^*:=-(A_{\Gamma_*}A_{\Gamma_*}^{\top})^{-1}A_{\Gamma_*}\nabla f(  \bfx^*)$. Clearly, both $\tau_1>0$ and $\tau_2>0$. Based on these notation, we have the following main result of this section.


\begin{assumption} \label{ass}
	 Suppose $f$ is twice continuously differentiable, $\nabla^2 f(\bfx^*)$ is {positive definite} and $A_{\Gamma_*}$ is full row rank, where $\Gamma_*$ is given by (\ref{T-*}).
 \end{assumption}

\begin{assumption} \label{ass2} 
Suppose $\nabla^2 f$ is locally Lipschitz continuous around $\bfx^*$ with a constant $L_*>0$, namely 
\begin{eqnarray*} \|\nabla^2 f(\bfx)-\nabla^2 f(\bfx')\|\leq L_* \|   \bfx -\bfx' \| \end{eqnarray*}
for any $\bfx$ and $\bfx'$ in the neighbourhood of $\bfx^*$.
 \end{assumption}

 For a point  $\bfw:=(\bfx; \bfz)$, we define the sets {
\begin{eqnarray}\label{p-stationary-T}
\arraycolsep=1.4pt\def\arraystretch{1.5}
 \begin{array}{rcll}
\S&:=& \left\{i\in\N_m:  A_i\bfx+b_i+\tau z_i   \in (0, \sqrt{2\tau\lambda}) \right\}, \\
 \E&:=& \left\{i\in\N_m: A_i\bfx+b_i +\tau z_i \in\{0,\sqrt{2\tau\lambda}\} \right\},\\
\O&:=& \left\{i\in\N_m:  A_i\bfx+b_i+ \tau z_i \in(-\infty,0)\cup ( \sqrt{2\tau\lambda},\infty) \right\},\\
\E^o&:=& \left\{i\in\N_m: A_i\bfx+b_i =0, \tau z_i   \in\{0,\sqrt{2\tau\lambda}\} \right\}, 
\end{array}
\end{eqnarray}

for a given $\tau>0$. 
%The first three sets stand for index sets on which the value $|A_i\bfx+b_i+\tau z_i-\sqrt{\tau\lambda/2}|$ is smaller than, equal to and over than $\sqrt{\tau\lambda/2}$, respectively. 
Obviously, $\E^o\subseteq \E.$ 
It is worth mentioning that all sets depend on $\bfw$. 
For simplicity, we drop their dependence whenever 
there is no confusion to be caused. 
Same rules are also applied into $\S_*,\E_*,\O_*$ and $\E_*^o$ for  $\bfw^*:=(\bfx^*; \bfz^*)$. 


\begin{eqnarray}
\label{sta-eq-1}
\hspace{8mm} F(\bfw; \Gamma) =\left[\begin{array}{rrl}
\nabla f(\bfx)  + A_{\Gamma}^\top \bfz_{\Gamma}  \\
A_{\Gamma} \bfx + \bfb_{\Gamma} \\
\bfz_{\overline \Gamma} 
\end{array}
\right] = 0, \quad 
%\label{def-Jacobian}
\nabla F_{\mu}(\bfw;\Gamma) =\left[\begin{array}{ccc}
\nabla^2 f(\bfx)   & A_{\Gamma} ^\top &0\\
A_{\Gamma} &-\mu I&0 \\
0&0&I
\end{array}
\right].
\end{eqnarray}

We note that the matrix $\nabla F_{\mu}$ is a slight perturbation of
the Jacobian matrix of $F$ and 
$\nabla F(\bfw;\Gamma)=\nabla F_{0}(\bfw;\Gamma)$,


Let $\bfw^k:=(\bfx^k; \bfz^k)$ be the current iterate.
We define $\S_k$ and $\E_k^o$ by \eqref{p-stationary-T} with $\bfw$ being replaced by $\bfw^k$ and let  


\beq \label{T-k}
      T_k := \S_k\cup \E_k^o.  
 \eeq

Let $\bfd^k=(\bfu^k;\bfv^k)$ with $\bfu^k\in\R^n$ and $\bfv^k\in\R^{m}$. For 
such a defined $T_k$, a Newton direction $\bfd^k$ for the equation \eqref{sta-eq-1} solves the following linear equations:


\[ %\beq \label{newton-d}
 \nabla F(\bfw^k;T_k)~\bfd = - F(\bfw^k;T_k). 
 \]

To improve the nonsingularity of the Jacobian matrix $\nabla F(\bfw^k;T_k)$,
we replace it with $\nabla F_{\mu_k}(\bfw^k;T_k)$. 
That is, at $\bfw^k$, we solve the equation:


\beq \label{newton-dir-0}
 \nabla F_{\mu_k}(\bfw^k;T_k)~\bfd = - F(\bfw^k;T_k), 
 \eeq

where $\nabla F_{\mu_k}(\bfw^k;T_k)$ is  defined in \eqref{sta-eq-1}.
The Newton direction $\bfd^k$ satisfies 


\beq \label{newton-dir} 
 \left[  
     \begin{array}{ccc}
     {\nabla^2  f(\bfx^k)}& A_{T_k}^\top&0\\
   A_{T_k}&-\mu_k I&0\\
    0&0&I
     \end{array}
     \right]  
     \left[  
     \begin{array}{l}
    \bfu^k\\
    \bfv^k_{T_k}\\
    \bfv^k_{\overline T_k}
     \end{array}
     \right]
     =-\left[  
     \begin{array}{r}
    \nabla  f(\bfx^k)+A_{T_k}^\top\bfz^k_{T_k}\\
   A_{T_k}\bfx^k+\bfb_{T_k} \\
    \bfz^k_{\overline T_k}
     \end{array}
     \right].
 \eeq

Here, the rule to update $\mu_k$ is as follows:


\beq \label{update-mu} 
\mu_{k}=
\min\{\alpha \mu_{k-1}, \rho\|F(\bfw^k;T_k)\|\},
 \eeq

 where $\alpha\in(0,1)$ and $\rho>0$. Now we summarize   the proposed method in  \cref{Alg-NM01}. 
\begin{algorithm}[H]
	\caption{\nhs: Newton's method for $0/1$-loss optimization}
	\begin{algorithmic}[1] \label{Alg-NM01}
		%\scriptsize
		\STATE Initialize $\bfw^0=(\bfx^0;\bfz^0)$ and $\mu_{-1}>0$. Set the parameter $\tau,\lambda,\rho>0, \alpha\in(0,1)$.\\
		 Compute $T_0$ by \eqref{T-k} and set $k :=0$.
\IF{ $\|F(\bfw^k;T_k)\|>0$}		 
         \STATE  Update $\mu_{k}$ by \eqref{update-mu}.	
		\STATE  Update $\bfd^k$ by solving \eqref{newton-dir}.
		\STATE  Update $\bfw^{k+1}~=~\bfw^k+\bfd^k$.
		\STATE  Update $T_{k+1}$ by \eqref{T-k} and  set $k := k+1$.   		
\ENDIF		
\RETURN $\bfw^{k}$.
	\end{algorithmic}
\end{algorithm}

The first technical result is about extending the stationarity equation to some indices that are given in a neighborhood of $\bfw^*$. In the proof, we recall $\bfy = A\bfx+\bfb$ and $\bfy^* = A\bfx^*+\bfb$.

