proof.raw_tex:
\begin{lemma} \label{subdifferentials}

\begin{itemize}

 \item[(i)] We have
 \begin{eqnarray}\label{subfi}
  \partial\|{\bfy}_+\|_0
  =\left\{{\bfv}\in {\R}^m: v_i\left\{\begin{array}{ll}
 \geq0,& y_i=0,\\
 =0,& y_i\neq0,
 \end{array}
 \right. i\in{\N}_m\right\}. 
 \end{eqnarray}

 \item[(ii)] Let $g(\bfx):=\|(h(\bfx))_+\|_0$, where $h:\R^n\rightarrow\R^m$ is differentiable,  and $\Gamma:=\{i\in\N_m: h_i(  \bfx)=0\}$ for a given a point $ \bfx\in\R^n$.  If 
 \begin{eqnarray}
 \label{chain-rule-cond}
 \left.
 \begin{array}{r}
 \forall \bfz\in\R^{|\Gamma|},~~\bfz\geq 0,~~
 (\nabla h( \bfx))_{\Gamma}^\top \bfz = 0
 \end{array}\right.~~\Longrightarrow~~\bfz = 0,
 \end{eqnarray}
 then the subdifferential of $g(\bfx)$  at $  \bfx$ is  
 \begin{eqnarray}
 \label{chain-rule-sub} 
 \partial g(  \bfx)=\nabla h( \bfx)^\top \partial \|(h(  \bfx))_+\|_0.
 \end{eqnarray}

\end{itemize}
\end{lemma}

\begin{proof}
i)   It is straight to check that the regular subdifferential $\widehat{\partial}\|{\bfy}_+\|_0$ (see \cite[Definition 8.3]{RW1998})  of $\|{\bfy}_+\|_0$ at ${\bfy}$ takes the following form,
\begin{eqnarray}\label{subfi-0}
 \widehat{\partial}\|{\bfy}_+\|_0=\left\{{\bfv}\in {\R}^m: v_i\left\{\begin{array}{ll}
 \geq0,& y_i=0,\\
 =0,& y_i\neq0,
 \end{array}
 \right. i\in{\N}_m\right\}=:\Omega(\bfy). 
\end{eqnarray}
We next verify $ \partial\|{\bfy}_+\|_0= \Omega({\bfy}) $. By letting $\varphi(\cdot):=\|(\cdot)_+\|_0$, we have
  \begin{eqnarray}\label{sub-lim-reg}
  \arraycolsep=1.4pt\def\arraystretch{1.5}
  \begin{array}{rclll}
\partial\|{\bfy}_+\|_0&=&\limsup_{{\bfz}\stackrel{\varphi}{\rightarrow}{\bfy}}~ \widehat{\partial}\|{\bfz}_+\|_0 ~~~( \text{by  \cite[Equation 8(5)]{RW1998}})\\
&=&\limsup_{{\bfz}\stackrel{\varphi}{\rightarrow}{\bfy}}~\Omega({\bfz}) ~~~~~~( \text{by \eqref{subfi-0}})\\
&=&\{\bfv\in \R^m:\exists~\bfz^k\stackrel{\varphi}{\rightarrow} \bfy,~\bfv^k\rightarrow \bfv ~\text{with}~\bfv^k\in \Omega(\bfz^k) \}=:\Theta,
\end{array}
 \end{eqnarray}
where  $\bfz\stackrel{\varphi}{\rightarrow} \bfy$ represents $\bfz\rightarrow \bfy, \varphi(\bfz)\rightarrow \varphi(\bfy)$. Clearly, $\Omega({\bfy})\subseteq\Theta$. On the other hand, $\Theta \subseteq \Omega({\bfy})$  follows from that $\Omega(\bfz^k)\subseteq \Omega(\bfy)$ for any $\bfz^k\stackrel{\varphi}{\rightarrow} \bfy$ and $\Omega(\cdot)$ is closed.

 ii) Direct verifications yield the following chain of equations,
 \begin{eqnarray*}  \arraycolsep=1.4pt\def\arraystretch{1.5}
  \begin{array}{rclll}
 \partial^\infty \|\bfy_+\|_0&=& {\limsup}_{\sigma\downarrow0,~{\bfz}\stackrel{\varphi}{\rightarrow} {\bfy}} \sigma \widehat{\partial}\|\bfz_+\|_0&~~( \text{by \cite[Equation 8(5)]{RW1998}})\\ 
&=&
 {\limsup}_{{\bfz}\stackrel{\varphi}{\rightarrow} {\bfy}}~ \widehat{\partial}\|\bfz_+\|_0&~~( \text{by \eqref{subfi-0}})\\
 & =& \partial\|{\bfy}_+\|_0,&~~( \text{by \eqref{sub-lim-reg}})\\
 \end{array}
 \end{eqnarray*}
 where $ \partial^\infty \|{\bfy}_+\|_0$ is the horizon subdifferential of $\|{\bfy}_+\|_0$. Therefore, we derive that $\widehat{\partial}\varphi=\partial \varphi=\partial^\infty \varphi$.  One can easily prove that the horizon cone $\widehat{\partial}\varphi(\bfy)^\infty$ (see \cite[Definition 3.3]{RW1998}) of $ \widehat{\partial}\varphi(\bfy)$ satisfies $\widehat{\partial}\varphi(\bfy)^\infty = \partial^ \infty\varphi(\bfy)$. These conditions indicate that  the function $\varphi$ is regular by \cite[Corollary 8.11]{RW1998}, which together with \eqref{chain-rule-cond}, $g(\bfx)=\varphi(h(\bfx))$ and \cite[Theorem 10.6]{RW1998} derives \eqref{chain-rule-sub} immediately. 
\end{proof}

\begin{lemma}\label{first-order-nec}
	The following relationships hold for the problem (\ref{ell-0-1}).
\begin{itemize}

\item[i)] A local minimizer $\bfx^*$   satisfies the following condition 
         if  $A_{\Gamma_*}$ is full row rank,
\begin{eqnarray} \label{lemma-1st-order-nec}
    -\nabla f(\bfx^*) \in A^\top \partial \|(A\bfx^*+\bfb)_+\|_0.
\end{eqnarray}

\item[ii)] A point $\bfx^*$ satisfying (\ref{lemma-1st-order-nec})  is a local minimizer if  the function $f$ is locally convex around $\bfx^*$.
\end{itemize}
\end{lemma}

\begin{proof}
i) It follows from \cite[Theorem 10.1]{RW1998} that a local minimizer of \eqref{ell-0-1} must satisfy $-\nabla f(\bfx^*)\in\lambda\partial g(\bfx^*)$, where $g(\bfx):=\|(A\bfx+\bfb)_+\|_0$. This together with \cref{chain-rule-sub}  and $\lambda \partial\|(\cdot)_+\|_0 = \partial \|(\cdot)_+\|_0$ by \eqref{subfi} derives the result immediately.  

ii)   Since the problem \eqref{ell-0-1} is equivalent to the following problem, 
\begin{eqnarray}\label{ell-0-1-equ-0}
&\underset{\bfx\in\R^n,\bfy\in\R^m}{\min}& f(\bfx)+\lambda \|\bfy_+\|_0,\\
  &{\rm s.t.}& A\bfx+\bfb-\bfy = 0,\nonumber
\end{eqnarray}
it suffices to show that  $(\bfx^*;\bfy^*)$  is a local minimizer of the   problem \eqref{ell-0-1-equ-0}, where $\bfx^*$ satisfies \eqref{lemma-1st-order-nec} and $\bfy^*=A \bfx^*+\bfb$, namely, there is a $\bfz^*$ such that
\begin{eqnarray}
\label{lemma-1st-order-nec-10}
\nabla f(\bfx^*) +A^\top\bfz^*=0,~~ 
A \bfx^*+\bfb-\bfy^*=0, ~~
\partial\|\bfy^*_+\|_0\ni \bfz^*. 
\end{eqnarray} 
It follows from $\bfy^*=A\bfx^*+\bfb$ and \eqref{T-*} that $\Gamma_*=\{i\in\N_m: y^*_i=0\}$. This together with $\partial\|\bfy^*_+\|_0 \ni \bfz^*$ and the expression of the $\partial\|\bfy^*_+\|_0$ in  \eqref{subfi} indicates 
\begin{eqnarray}\label{fact-11}
\bfy_{\Gamma_*}^*=0,~~\bfz_{\Gamma_*}^* \geq 0, ~~~~\bfy_{\overline \Gamma_*}^*\neq 0,~ ~\bfz_{\overline \Gamma_*}^* = 0. 
\end{eqnarray} 
 Define a radius $\delta:=\min\{\delta_1,\delta_2\}$, where
\begin{eqnarray}\label{delta-2}
~~~~~~\delta_1 := 
\begin{cases}
+\infty,&A_{\Gamma_*}^\top\bfz^* _{\Gamma_*}=0\\
\frac{\lambda}{ \|A_{\Gamma_*}^\top\bfz^* _{\Gamma_*}\|},& \text{otherwise}, 
\end{cases}~~~~
\delta_2 := 
\begin{cases}
+\infty,&\bfy^*\leq {\bf0},\\
\min_i\{y_i^*:y_i^*>0\},&\text{otherwise}, 
\end{cases}
\end{eqnarray}
and consider a local region of ${\bfw}^* := (\bfx^*;\bfy^*)$ by
\begin{eqnarray}\label{local-area-1}
~~N( {\bfw}^*,\delta)=\left\{ \left(
\bfx; 
  {\bfy}\right)\in\R^{n+m}   
:~A\bfx+\bfb - \bfy=0, ~
 \|{\bfw}- {\bfw}^*\|<\delta
\right\}.
\end{eqnarray}
Indeed, $N( {\bfw}^*,\delta)$ is a neighbourhood of ${\bfw}^*$ since $A\bfx^*+\bfb - \bfy^*=0$ from \eqref{lemma-1st-order-nec-10}. Next we show that, for any $\bfw\in N( {\bfw}^*,\delta)$,
\begin{eqnarray}\label{y-y*-0}
\|\bfy^*_+\|_0\leq \|\bfy_+\|_0.
\end{eqnarray}
Obviously, it is true if $\bfy^*\leq0$ as $\|\bfy^*_+\|_0=0$. For $\bfy^*\nleq0$,  to guarantee \eqref{y-y*-0}, it suffices to show that for any $i$, $y_i^*>0~\Longrightarrow~y_i>0.$ 
Suppose there is a $j\in\N_m$ such that $y_j^*>0$ but $y_j\leq0$.  This incurs the following contradiction 
\begin{eqnarray*}\delta_2 \geq \delta
& {>}&\|\bfw-\bfw^*\| \hspace{3.5cm} ({\rm by}~ \eqref{local-area-1})\\
&\geq& |y_j-y_j^*|=y_j^*-y_j  \geq y_j^*\geq\delta_2.\hspace{.5cm} ({\rm by}~ \eqref{delta-2}) \end{eqnarray*}
Again, for any $\bfw\in N( {\bfw}^*,\delta)$, we have $A\bfx+\bfb - \bfy=0$, which and \eqref{lemma-1st-order-nec-10} generate
 \begin{eqnarray}\label{y-y*-h-h*}
 \bfy-\bfy^*=A (\bfx- \bfx^*).
  \end{eqnarray}
Next, the convexity of $f$ gives rise to  
 \begin{eqnarray}\label{fx-fx*}
\hspace{15mm} f(\bfx)-f(\bfx^*)&\geq & \langle \nabla f(\bfx^*), \bfx - \bfx^*\rangle~~= -\langle  A^\top \bfz^* , \bfx - \bfx^*\rangle \hspace{1.6cm} ({\rm by}~ \eqref{lemma-1st-order-nec-10})\nonumber\\
% &=& -\langle  A_{\Gamma_*}  (\bfx - \bfx^*),\bfz^* _{\Gamma_*}\rangle-\langle   A_{\overline  \Gamma_*} (\bfx - \bfx^*),\bfz^* _{\overline  \Gamma_*}\rangle\nonumber\\
 &=& -\langle  A_{\Gamma_*}^\top\bfz^* _{\Gamma_*},\bfx - \bfx^*\rangle= -\langle  A_{\Gamma_*}(\bfx - \bfx^*),\bfz^* _{\Gamma_*}\rangle=:\phi\hspace{0.3cm} ({\rm by}~ \eqref{fact-11})
  \end{eqnarray} 
 Now we make the conclusion by two cases.  
 If $\|\bfy^*_+\|_0= \|\bfy_+\|_0$, then   $\bfy_{\Gamma_*}\leq 0$ due to $\bfy^*_{\Gamma_*}=0$. This and \eqref{y-y*-h-h*} yield that
  \begin{eqnarray}\label{y-y*-h-h*-0}
0\geq  \bfy_{\Gamma_*}= \bfy_{\Gamma_*}-\bfy^*_{\Gamma_*}  = A_{\Gamma_*} (\bfx-\bfx^*),
  \end{eqnarray}
which together with $\bfz^* _{\Gamma_*}\geq0$ from \eqref{fact-11} indicates $\phi\geq0$, namely $f(\bfx)\geq f(\bfx^*)$. So $$f(\bfx) +\lambda \|\bfy_+\|_0 \geq f(\bfx^*) + \lambda\|\bfy_+^*\|_0.$$
If $\|\bfy^*_+\|_0 \neq \|\bfy_+\|_0$, we must have $ \|\bfy_+\|_0 \geq 1+\|\bfy^*_+\|_0$ by \eqref{y-y*-0}. If  $A_{\Gamma_*}^\top\bfz^* _{\Gamma_*}=0$, then $\phi=0>-\lambda$. Otherwise, it follows
  \begin{eqnarray*}
\phi&\geq&- \|A_{\Gamma_*}^\top\bfz^* _{\Gamma_*}\|\|\bfx - \bfx^*\| \geq - \|A_{\Gamma_*}^\top\bfz^* _{\Gamma_*}\|\|\bfw - \bfw^*\|\\
 & \geq&- \|A_{\Gamma_*}^\top\bfz^* _{\Gamma_*}\|\delta 
  \geq - \|A_{\Gamma_*}^\top\bfz^* _{\Gamma_*}\|\delta_1=-\lambda.\hspace{.5cm} ({\rm by}~ \eqref{delta-2})
  \end{eqnarray*}
Both lead to $\phi\geq-\lambda$, which results in
  \begin{eqnarray*}\arraycolsep=1.4pt\def\arraystretch{1.5}
  \begin{array}{rclll}
  f(\bfx) +\lambda \|\bfy_+\|_0 &\geq& f(\bfx^*) + \phi +\lambda \|\bfy_+\|_0 &\ ({\rm by}~ \eqref{fx-fx*} )\\
&\geq& f(\bfx^*) -\lambda + \lambda\|\bfy_+\|_0 &\ ({\rm by}~ \phi\geq-\lambda)\\
&\geq& f(\bfx^*) + \lambda\|\bfy_+^*\|_0.&\ ({\rm by}~ \|\bfy_+\|_0 \geq 1+\|\bfy^*_+\|_0 )
 \end{array} \end{eqnarray*}
Overall, the two cases show that $(\bfx^*;\bfy^*)$ is  a local minimizer to \eqref{ell-0-1-equ-0}. Namely, $\bfx^*$ is  a local minimizer to \eqref{ell-0-1}. 
\end{proof}

\begin{theorem} \label{Stationary-Thm}
   The following relationships hold for the problem (\ref{ell-0-1}).
\begin{itemize}
\item[i)]  A local minimizer $\bfx^*$ is a  P-stationary point for any $0<\tau<\tau_*:=\min\{\tau_1,\tau_2\}$ if  $A_{\Gamma_*}$ is full row rank. 
\item[ii)] A P-stationary point with $ \tau>0$  is a local minimizer if  the function $f$ is locally convex around $\bfx^*$. 
\item[iii)] A P-stationary point with $ \tau\geq\|A\|^2/c_f$  is   a global minimizer if  the function $f$ is strongly convex with a constant $c_f>0$.
\end{itemize}
\end{theorem}

\begin{proof} i) As  $\bfx^*$ is a local minimizer of \eqref{ell-0-1},  condition  \eqref{lemma-1st-order-nec} is valid by \cref{first-order-nec} if $A_{\Gamma_*}$ is  full row rank. In other words, there is a $\bfz^*$ such that
\begin{eqnarray}
\label{lemma-1st-order-nec-1}
\nabla f(\bfx^*) +A^\top\bfz^*=0,~~
A \bfx^*+\bfb-\bfy^*=0,~~
\bfz^*\in\partial\|\bfy^*_+\|_0. 
\end{eqnarray} 
Therefore, to show \eqref{p-stationary}, we only need to verify that,  for any $0<\tau<\tau^*$, $$\bfz^*\in \partial\|\bfy^*_+\|_0~ \Rightarrow~\bfy^*\in\P :=\pro (\bfy^*+\tau \bfz^*). $$ 
Recall the definition of $\Gamma_*$ in \eqref{T-*} and the second condition in \eqref{lemma-1st-order-nec-1}, we have $\bfy_{\Gamma_*}=(A \bfx^*+\bfb)_{\Gamma_*}=0$. Same reasoning also allows for obtaining \eqref{fact-11} due to $\bfz^*\in \partial\|\bfy^*_+\|_0$. 
As $A_{\Gamma_*}$ is full row rank, the first condition in \eqref{lemma-1st-order-nec-1} and  $A^\top\bfz^*  =A_{\Gamma_*}^\top\bfz^*_{\Gamma_*}$ derive  that
$$\bfz^*_{\Gamma_*}=\bfp^*.$$
Now, $0<\tau<\tau_*= \min\{\tau_1,\tau_2\}$ in \eqref{tau-*} results in 
\begin{eqnarray}\label{non-negative}
\arraycolsep=1.4pt\def\arraystretch{1.5}
\begin{array}{lllllllllll}
 y_i^*  & \geq & \underset{i:y^*_i>0}{\min} y^*_i &=&  \sqrt{2\tau_1\lambda}&\geq&\sqrt{2\tau_*\lambda} &>&\sqrt{2\tau \lambda}  &~~\text{if}~~& y_i^*>0,\\ 
   z_i^* & \leq &  {\underset{i}{\max}|p^*_i|} &= &\sqrt{2\lambda/\tau_2}&\leq&\sqrt{2\lambda/\tau_*}&< &\sqrt{2\lambda/\tau}& ~~ \text{if}~~ &z_i^*>0.
\end{array}
\end{eqnarray}
These and \eqref{fact-11}  yield the following condition,
\begin{eqnarray*} 
y_i^*\begin{cases}
=0, &   z_i^*=0 ~{\rm or}~ 0< z_i^* < \sqrt{2\lambda/\tau},\\
<0 ~{\rm or}~>\sqrt{2\tau\lambda },& z_i^*=0. 
\end{cases}
\end{eqnarray*}
  {It is easy to see that the above condition satisfies that 
\begin{eqnarray}\label{ugTT-1}
y_i^*  \in \P_i=
\begin{cases}
0, & y_i^*+\tau z_i^*\in(0, \sqrt{2\tau\lambda}),\\
0~{\rm or}~ y_i^*+\tau z_i^*, &y_i^*+\tau z_i^*\in\{0, \sqrt{2\tau\lambda}\},\\
y_i^*+\tau z_i^*,& y_i^*+\tau z_i^*\in(-\infty,0)\cup ( \sqrt{2\tau\lambda},\infty).
\end{cases}
\end{eqnarray}}



ii) Note that the second condition in \eqref{p-stationary} means $\bfy^*\in\P$, which by   \eqref{ugTT-1} implies $z_i^*=0$ if $y_i^*\neq 0$ and  $z_i^*\geq0$ if $y_i^*= 0$, resulting in $\bfz^*\in\partial\|\bfy^*_+\|_0$ by \eqref{subfi}. Consequently, we obtain \eqref{lemma-1st-order-nec-1} and \eqref{lemma-1st-order-nec}.
% In other words, a  P-stationary point satisfies \eqref{lemma-1st-order-nec} and thus is a local minimizer  if  $f$ is locally convex around $\bfx^*$ by
The claim follows from  \cref{first-order-nec} ii).


iii) Let $(\bfx^*;\bfz^*)$ be a  P-stationary point with $ \tau\geq\|A\|^2/c_f$. Then the second condition in \eqref{p-stationary} indicates that
\beq
&&({1}/{2\tau})\|A\bfx^*+\bfb-(A\bfx^*+\bfb+\tau \bfz^*)\|^2+\lambda\|(A\bfx^*+\bfb)_+\|_0 \nonumber \\
&\leq& ({1}/{2\tau})\|A\bfx+\bfb-(A\bfx^*+\bfb+\tau \bfz^*)\|^2+\lambda\|(A\bfx+\bfb)_+\|_0\nonumber
\eeq
for any $\bfx\in\R^n$, which after simplifying leads to 
\beq\label{Ax*b-Axb}
&& \lambda\|(A\bfx^*+\bfb)_+\|_0 - \|A(\bfx-\bfx^*)\|^2 /(2\tau) \nonumber\\
&\leq& \lambda\|(A\bfx+\bfb)_+\|_0 - \langle  \bfz^*, A(\bfx-\bfx^*) \rangle\nonumber\\
&=& \lambda\|(A\bfx+\bfb)_+\|_0 - \langle  A^\top \bfz^*, \bfx-\bfx^*    \rangle\nonumber\\
&=& \lambda\|(A\bfx+\bfb)_+\|_0 + \langle  \nabla f(\bfx^*), \bfx-\bfx^*  \rangle. \hspace{.5cm} ({\rm by}~  \eqref{p-stationary}) 
\eeq
The strong convexity of $f$ implies
\begin{eqnarray*} 
&&f(\bfx)+\lambda\|(A\bfx+\bfb)_+\|_0-f(\bfx^*)-\lambda\|(A\bfx^*+\bfb)_+\|_0\\
&\geq&({c_f}/{2})\|\bfx-\bfx^*\|^2+\langle  \nabla f(\bfx^*), \bfx-\bfx^*   \rangle+\lambda\|(A\bfx+\bfb)_+\|_0-\lambda\|(A\bfx^*+\bfb)_+\|_0\\
&\geq&({c_f}/{2})\|\bfx-\bfx^*\|^2-1/({2\tau})\|A(\bfx-\bfx^*)\|^2    \hspace{.25cm} ({\rm by}~  \eqref{Ax*b-Axb})\\
&\geq&({c_f/2-\|A\|^2/(2\tau}))\|\bfx-\bfx^*\|^2   \geq 0. \hspace{1cm} ({\rm by}~  \tau\geq\|A\|^2/c_f) 
\end{eqnarray*}
This shows the global optimality of $\bfx^*$ to the problem \eqref{ell-0-1}.
\end{proof}

\begin{theorem}\label{cor-p-staionary}
A point $\bfw^*=(\bfx^*;\bfz^*)$ is a  P-stationary point with $\tau>0$ of the problem (\ref{ell-0-1}) if and only if   $F(\bfw^*; \Gamma_*)=0$ and $ \Gamma_*=(\S_* \cup \E^o_*)$, where $\Gamma_*$ is defined by (\ref{T-*}).
%the following equations hold
