%A_{\Gamma_*} \bfx^* + \bfb_{\Gamma_*} \\
%\bfz^*_{\overline \Gamma_*} 
%\end{array}
%\right]=0. 
%\end{eqnarray} 
The Jacobian  $\nabla F(\bfw^*;\Gamma_*)$ is   non-singular if \cref{ass} holds.
\end{theorem}

\begin{proof} 
The second claim is obvious due to Assumption \ref{ass}.
 We only need to prove the first claim. 
We start with the sufficiency.
 The definitions  in \eqref{p-stationary-T} show the following relationships,
\beq\label{TSE}
\Gamma_*= \S_* \cup \E^o_*,~~~~\overline{\Gamma}_*=\O_*\cup(\E_* \setminus \E^o_*).
\eeq
We recall $\bfy^*=A\bfx^*+\bfb$ and $\P:=\text{Prox}_{\tau\lambda\|({\cdot})_{+}\|_{0}}( \bfy^*+\tau \bfz^*)$.
It follows that 
 \allowdisplaybreaks \begin{eqnarray*} 
 \P_i 
=
\begin{cases}
0, & i\in \S,\\
0~{\rm or}~y^*_i+\tau z^*_i, &i\in\E_*,\\
 y_i+\tau z^*_i,& i\in \O_*,
\end{cases} 
=
\begin{cases}
0, & i\in \S_*\subseteq \Gamma_*,\\
0~{\rm or}~\tau z^*_i, &i\in \E^o_* \subseteq \Gamma_*,\\
0~{\rm or}~ y^*_i, &i\in(\E_*\setminus \E^o_*) \subseteq \overline \Gamma_*,\\
y^*_i,& i\in \O_*\subseteq \overline \Gamma_*,
\end{cases} 
\end{eqnarray*}
where the first equation is by \eqref{proximal-operator} and second one is by \eqref{sta-eq-1} and \eqref{TSE}, which indicates $y^*_i \in \P_i$ due to $ \bfy^*_{\Gamma_*}=0$ from \eqref{sta-eq-1}. Moreover,   
the first and third equations in \eqref{sta-eq-1} suffice to $\nabla f(\bfx^*)  + A^\top \bfz^*  =  0$, showing \eqref{p-stationary}. Namely,  $ \bfw^*$ is a  P-stationary point. 

{Necessity.}  Let $ \bfw^*$ be a  P-stationary point satisfying \eqref{p-stationary} and $T_*:= \S_* \cup \E^o_*$.  Then $\overline{T}_*=\O_*\cup(\E_* \setminus \E^o_*)$. It follows from $y^*_i\in \P_i$ and \eqref{proximal-operator} that
\begin{eqnarray*} 
y^*_i\in 
%\Big[\text{Prox}_{\gamma C\|({\cdot})_{+}\|_{0}}(  \bfy^*+\tau \bfz^*)\Big]_i \\
\begin{cases}
0, & i\in \S_*,\\
0~{\rm or}~ y^*_i+\tau z^*_i, &i\in\E_*,\\
y^*_i+\tau z^*_i,& i\in \O_*,
\end{cases} =
\begin{cases}
0, & i\in \S_*,\\
0~{\rm or}~\tau z^*_i, &i\in\E^o_*,\\
0~{\rm or}~ y^*_i+\tau z^*_i, &i\in\E_*\setminus \E^o_*,\\
y^*_i+\tau z^*_i,& i\in \O_*,
\end{cases} 
\end{eqnarray*}
where the equality is by the definition  of $\E^o_*$, which together with $ y^*_i= 0 , i\in \E^o_*$ and $y^*_i\neq 0, i\in \E_*\setminus \E^o_*$ suffices to
\begin{eqnarray*} 
\begin{cases}
y^*_i=0, & i\in \S_*\cup\E^o_*=T_*,\\
y^*_i = y^*_i+\tau z^*_i, &i\in\E_*\setminus \E^o_*,\\
y^*_i= y^*_i+\tau z^*_i,& i\in \O_*,
