This gives rise to the last two conditions $\bfy^*_{T_*}=0,~
\bfz^*_{\overline T_*}=0$  in \eqref{sta-eq-1}. 
Furthermore, the first condition in \eqref{p-stationary} and $\bfz^*_{\overline{T}_*}=0$ derive the first condition of \eqref{sta-eq-1}.
Overall, we have $F(\bfw^*; T_*)=0$. 
Now we show $T_*=\Gamma_*$. By  (\ref{T-*}) that $\Gamma_*=\{i\in\N_m: y^*_i=0\}$, it follows $T_*\subseteq \Gamma_*$. Suppose, there is a $j\in \Gamma_*$ but $j\notin T_*$, then
we have $y_j^*=z_j^*=0$ and thus $j\in \E^o_* \subseteq T_*$  by \eqref{p-stationary-T}, a contradiction. Therefore, $T_*=\Gamma_*$, finishing the proof. \end{proof}

\begin{lemma}\label{lemma-neighbour-1}
	 Let $\bfw^*$ be a \ts\  with $0<\tau<\tau_*:=\min\{\tau_1,\tau_2\}$ of the problem (\ref{ell-0-1}),  $\tau_1,\tau_2$ and $\Gamma_*$  be given by (\ref{tau-*}) and (\ref{T-*}).  Then there is a $\delta_1^*>0$ such that, for any $\bfw\in N(\bfw^*,\delta_1^*)$ with its associated indices $\S$ and $\E^o$, it holds 
 \beq\label{gw*-0} 
 F(\bfw^*;T)=0 ~~~~{\rm and}~~~T:=(\S\cup\E^o)\subseteq \Gamma_*.
 \eeq
\end{lemma}

\begin{proof} i) \cref{cor-p-staionary} states that the \ts\ $\bfw^*$ of (\ref{ell-0-1}) satisfies
\begin{eqnarray}
\label{sta-eq-1-*}
\nabla f(\bfx^*)  + A_{\Gamma_*} \bfz^*_{\Gamma_*}=0,~~
 \bfy^*_{\Gamma_*}=0, ~~
\bfz^*_{\overline \Gamma_*}  =0 
\end{eqnarray} 
 for $0<\tau<\tau_*$, where $\Gamma_*=\S_*\cup\E^o_*$. Note that $\E_*\setminus\E^o_*\subseteq \overline{\Gamma}_*$ which by \eqref{sta-eq-1-*} leads to
\begin{eqnarray} \label{sta-eq-1-*-z}
   \bfz^*_{\E_*\setminus\E^o_*}=0.
\end{eqnarray} 
Using the same reasoning for proving \eqref{non-negative},  
we can prove for $ 0<\tau<\tau_*= \min\{\tau_1,\tau_2\}$ in \eqref{tau-*} that
\begin{eqnarray} \label{yz-tau-lambda} 
 y_i^*  >\sqrt{2\tau\lambda}  ~~{\rm if}~~y_i^*> 0,~~~~~~ \tau z^*_i <   \sqrt{2\tau \lambda   } ~~{\rm if}~~z^*_i> 0.
\end{eqnarray}
Therefore,  we have the following facts {
