&=& \{i\in\N_m: y_i^*=0, z_i^*=0 \}, &~~(\text{by}~\eqref{yz-tau-lambda})\\
\E_*\setminus\E^o_*&=& \{i\in\N_m: y_i^*\neq0, y_i^*+\tau z_i^* = \sqrt{2\tau\lambda } \}&~~(\text{by} ~\eqref{p-stationary-T})\\
 &=& \{i\in\N_m: y_i^* = \sqrt{2\tau\lambda} \}&~~(\text{by}~\eqref{sta-eq-1-*-z})\\
&=&\emptyset, &~~(\text{by}~\eqref{yz-tau-lambda})
 \end{array}\end{eqnarray*}}
These facts lead to
\begin{eqnarray}\label{E*0}
\E_*=\E^o_*\cup(\E_*\setminus\E^o_*)=\E^o_*
=\Big\{i\in\N_m: y_i^*= z_i^*=0\Big\},
\end{eqnarray}
which yields the following relations
\begin{eqnarray}\label{TSETO}
\Gamma_*=\S_*\cup \E_*^o=\S_*\cup \E_*,~~~~\overline \Gamma_*= \O_*. 
\end{eqnarray}   
 {For a sufficiently small $\delta_1^*$, any $\bfw\in N(\bfw^*,\delta_1^*)$ satisfies,
\allowdisplaybreaks\begin{eqnarray}\label{hz-h*z*}
