\begin{lemma}\label{lemma-neighbour-2} Let $\bfw^*$ be a \ts\  with $0<\tau<\tau_*$ of the problem (\ref{ell-0-1}) and $\tau_*$ be given by (\ref{tau-*}).   Assume  \cref{ass} and \cref{ass2}. It holds 
 \beq \label{bd-jacobian-F-w-T}
  && C_*  \geq \|\nabla F_{\mu}(\bfw;T)\|\geq\sigma_{\min}( \nabla F_{\mu}(\bfw;T)) \geq   c_*>0, 
\eeq
for any $\bfw\in N(\bfw^*,\delta_2^*)$ and any $0\leq\mu\leq c_*/2$, where $T=\S\cup\E^o$ and
 \beq\label{radius-2}
C_*&:=&2\max\{1, \|H(\Gamma_*)\|\} ,~~~~ c_* := 0.5{\min\{1,\min_{\Gamma\subseteq\Gamma_*}\sigma_{\min}(H(\Gamma))\}}, \\
\label{H*}\delta_2^* &:=& \min\left\{\delta_1^*,   \frac{c_*}{ 2L_*}     \right\},~~~~H(\Gamma):=\left[  
     \begin{array}{ccc}
    \nabla^2 f(\bfx^*)& A^\top_{\Gamma}\\
     A_{\Gamma}&0
     \end{array}
     \right]. 
\end{eqnarray}
\end{lemma}

\begin{proof}  
Since  $\nabla^2 f(\bfx^*)$ is  {positive definite} and $A_{\Gamma_*}$ is full row rank by \cref{ass}, $A_\Gamma$ is full row rank for any $ \Gamma \subseteq   \Gamma_*$ and thus $H(\Gamma)$ is non-singular. 
We have $\sigma_{\min}(H(\Gamma)) > 0$ for any 
$ \Gamma \subseteq   \Gamma_*$ 
and  $c_*>0$. 
Now we build the bounds of $\nabla F_{\mu}(\bfw;T)$. 
For any given two matrices $D'$ and $D$, we have the first fact
\begin{eqnarray} \label{lower-bd-HH}
 \|D'-D\|
&\geq& \max_{i}|\sigma_i(D')-\sigma_i(D )|   \geq |\sigma_{i_0}( D')-\sigma_{i_0}(D)|\nonumber\\
&\geq& \sigma_{i_0}(D')-\sigma_{\min}(D) \geq \sigma_{\min}(D')-\sigma_{\min}(D), 
\end{eqnarray}
where the first inequality is from \cite[Reminder (2), on Page 76]{lutkepohl1996handbook} and  $i_0$ satisfies that $\sigma_{i_0}(D)=\sigma_{\min}(D)$.  Recall that
 \begin{eqnarray*}
 \label{FH*-FG}H(\Gamma)\overset{\eqref{H*}}{=}\left[  
     \begin{array}{ccc}
    \nabla^2 f(\bfx^*)& A^\top_{\Gamma }\\
     A_{\Gamma }&0
     \end{array}
     \right],~~~~ \nabla F(\bfw^*;T) =\left[  
     \begin{array}{cc}
    H(T)&0\\
     0&I  
     \end{array}
     \right].
    \end{eqnarray*}
For any $\bfw\in N(\bfw^*,\delta_2^*)$ and $\delta_2^*\leq\delta_1^*$,   \cref{lemma-neighbour-1} contributes to $T \subseteq   \Gamma_*$. So $H(T)$ is a submatrix of $H(\Gamma_*)$. Hence, %It follows from \cite[Theorem 1]{thompson1972principal} that the maximum  singular value of a  matrix is no less than the maximum singular value of its sub-matrix. Namely, 
\beq 
\|H(T)\| \leq \|H(\Gamma_*)\|,~~ \sigma_{\min}(H(T)) \geq \min_{\Gamma \subseteq \Gamma_*} \sigma_{\min} (H(\Gamma)),\nonumber
\eeq
where the latter is by $T \subseteq   \Gamma_*$, which gives us the second fact 
\beq\label{JJogG0}
\sigma_{\min}(\nabla F(\bfw^*;T))&=&\min\{1,\sigma_{\min}(H(T))\}\\
& \geq&\min\{1, \min_{\Gamma \subseteq \Gamma_*} \sigma_{\min} (H(\Gamma))\}=2c_*, \nonumber\\
\label{JJogG1}
\|\nabla F(\bfw^*;T)\| &=& \max\{1, \|H(T)\|\} \leq \max\{1, \|H(\Gamma_*)\|\} =C_*/2. 
\eeq
The locally Lipschitz continuity of $\nabla^2 f$  around $\bfx^*$ with $L_*$  yields the third fact,
\begin{eqnarray}
\label{HH*2}
\|\nabla F (\bfw^*;T)-\nabla F (\bfw;T)\|&=&\|\nabla^2  f (\bfx)-\nabla^2  f (\bfx^*)\|  \leq
   L_* \| \bfx -\bfx^* \| \nonumber\\
   &\leq& L_* \| \bfw -\bfw^* \| 
 \leq   L_* \delta_2^*
\leq c_*/2.   \hspace{.5cm}(\text{by}~\eqref{H*})
\end{eqnarray} 
Now these three facts allow us to derive
\allowdisplaybreaks 
\begin{eqnarray}\label{lower-bd-FF}
\arraycolsep=1.4pt\def\arraystretch{1.5}
\begin{array}{rclr}
&& \sigma_{\min}(\nabla F_{\mu}(\bfw;T))\\
 &\geq& \sigma_{\min}(\nabla F (\bfw ;T))- \|\nabla F(\bfw;T)-\nabla F_{\mu}  (\bfw;T)\| &(\text{by}~\eqref{lower-bd-HH})  \\
&=& \sigma_{\min}(\nabla F(\bfw ;T))- \mu &(\text{by}~\eqref{sta-eq-1}) \\
&\geq& \sigma_{\min}(\nabla F(\bfw^*;T))- \|\nabla F (\bfw^*;T)-\nabla F (\bfw;T)\|- \mu   &(\text{by}~\eqref{lower-bd-HH}) \\
&\geq&\sigma_{\min}(\nabla F(\bfw^*;T))- c_*/2 - \mu&(\text{by}~\eqref{HH*2}) \\
&\geq&\sigma_{\min}(\nabla F(\bfw^*;T))-  c_* &(\text{by}~\mu\leq c_*/2)   \\
&\geq&c_*. &(\text{by}~\eqref{JJogG0})  
\end{array}
\end{eqnarray}
Similarly, we also have
\allowdisplaybreaks 
\begin{eqnarray}\label{upper-bd-FF}
\arraycolsep=1.4pt\def\arraystretch{1.5}
\begin{array}{rclr}
&&\|\nabla F_{\mu}(\bfw;T)\|\\
 &\leq& \|\nabla F (\bfw ;T)\|+ \|\nabla F(\bfw;T)-\nabla F_{\mu}  (\bfw;T)\| \\
&=& \|\nabla F (\bfw ;T)\|+ \mu &(\text{by}~\eqref{sta-eq-1})\\
&\leq& \|\nabla F(\bfw^*;T)\|+ \|\nabla F (\bfw^*;T)-\nabla F (\bfw;T)\|+ \mu   &(\text{by}~\eqref{lower-bd-HH})  \\
&\leq& \|\nabla F(\bfw^*;T)\|+ c_*/2 + \mu&(\text{by}~\eqref{HH*2}) \\
&\leq& \|\nabla F(\bfw^*;T)\|+ c_* &(\text{by}~\mu\leq c_*/2)   \\
&\leq& C_*/2+c_* &(\text{by}~\eqref{JJogG1}) \\
&\leq& C_*. &(\text{by}~c_*\leq C_*/2)   
\end{array}
\end{eqnarray}
The whole proof is completed. 
\end{proof}

\begin{proof} a) It is easily observed   
\begin{eqnarray}\label{mu-k}
0< \mu_{k} \leq \mu_{k-1}, ~k=1,2,3,\ldots, ~~~~{\rm and}~~~~ \lim_{k\rightarrow\infty}\mu_k=0.
\end{eqnarray} 
It follows from \cref{lemma-neighbour-1} and the facts
$\delta_*\leq \delta_2^*\leq\delta_1^*$ and $\bfw^0\in N(\bfw^*,\delta_*)$ that     
\beq\label{F-w*-T0-0}F (\bfw^{*};T_0) =0  
\eeq
with $T_0=\S_0\cup\E_0^o$ and from \cref{lemma-neighbour-2} that     
\beq\label{grad-F-w*-T0-c} C_*  \geq \|\nabla F_{\mu_0}(\bfw^0;T_0)\|\geq\sigma_{\min}( \nabla F_{\mu_0}(\bfw^0;T_0)) \geq  c_*
\eeq
Here, we used the fact that $\mu_0\leq \mu_{-1}\leq c_*/2$ by  \eqref{mu-k}. 
From \eqref{newton-dir-0}, we have
\beq\label{dkt}
\nabla F_{\mu_0} (\bfw^{0};T_0)~\bfd^{0}=- F (\bfw^{0};T_0).
\eeq
  \cref{lemma-neighbour-2} states that $\nabla F_{\mu_0} (\bfw^{0};T_0)$ is non-singular and thus $\bfd^{0}$ is well defined.
Let 
\beq\label{w0-beta-w*}
\bfw^{0}_\beta= \bfw^{*} + \beta(\bfw^{0}-\bfw^{*})=(\bfx^{0}_\beta;\bfz^{0}_\beta)
\eeq
where $\beta\in[0,1].$ One can easily check that $\bfw^{0}_\beta\in N(\bfw^*,\delta_*)$ as $$\|\bfw^{0}_\beta-\bfw^{*}\|= \beta\|\bfw^{0}-\bfw^{*}\|\leq  \delta_*.$$
The definition  in \eqref{sta-eq-1} enables us to obtain
\allowdisplaybreaks 
\begin{eqnarray*}
\arraycolsep=1.4pt\def\arraystretch{1.5}
\begin{array}{rcll}
&&\|\nabla F_{\mu_0} (\bfw^{0};T_0)- \nabla F (\bfw^{0}_\beta;T_0) \|  \\
&\leq&\|\nabla^2 f(\bfx^0)- \nabla^2 f(\bfx^0_\beta)\| + \mu_0&(\text{by}~\eqref{sta-eq-1})  \\
& \leq& L_* \|\bfx^0-\bfx^0_\beta\|+ \rho  \|F(\bfw^0;T_0)\|&(\text{by}~\eqref{update-mu}) \\ 
& \leq& L_* \|\bfw^0-\bfw^0_\beta\|+ \rho \|\nabla F_{\mu_0} (\bfw^{0};T_0)\| \|\bfd^0\|&(\text{by}~\eqref{newton-dir-0}) \\ 
& \leq& L_* \|\bfw^0-\bfw^0_\beta\|+ \rho C_* \|\bfw^1-\bfw^0\|&(\text{by}~\eqref{grad-F-w*-T0-c}) \\ 
& \leq& L_*(1-\beta)\|\bfw^0-\bfw^*\|+ \rho C_* (\|\bfw^1-\bfw^*\|+\|\bfw^0-\bfw^*\|) &(\text{by}~\eqref{w0-beta-w*})  \\ 
& =& (L_*(1-\beta)+\rho C_*)\|\bfw^0-\bfw^*\|+ \rho C_* \|\bfw^1-\bfw^*\|.
\end{array} \end{eqnarray*}
Denote $\Theta_{\mu_0}:=\nabla F_{\mu_0} (\bfw^{0};T_0)$ and $\Theta(\beta):= \nabla F (\bfw^{0}_\beta;T_0)$.  The above condition yields
  \beq\label{lipschitz}
\arraycolsep=1.4pt\def\arraystretch{1.5}
\begin{array}{rcll}
 \int_0^1 \|\Theta_{\mu_0}  - \Theta(\beta)\|d\beta
\leq (L_*/2+\rho C_*)\|\bfw^0-\bfw^*\|+ \rho C_* \|\bfw^1-\bfw^*\|.
\end{array} \eeq
For the fixed $T_0$, the function $F(\cdot,T_0)$ is differentiable, which by \eqref{F-w*-T0-0} derives
\beq\label{mean-value}
\arraycolsep=1.4pt\def\arraystretch{1.5}
\begin{array}{rcll}
F (\bfw^{0};T_0)=F (\bfw^{*};T_0)+\int_0^1 \Theta(\beta)(\bfw^{0}-\bfw^{*})d\beta=\int_0^1 \Theta(\beta) (\bfw^{0}-\bfw^{*})d\beta.
\end{array}\eeq
Now the following chain of inequalities holds.
\begin{eqnarray*}
\arraycolsep=1.4pt\def\arraystretch{1.5}
\begin{array}{rcll}
c_*\|\bfw^{1}-\bfw^{*}\| &=& c_*\|\bfw^{0}+\bfd^{0}-\bfw^{*}\|\\
& {=} &c_*\|\bfw^{0}-\bfw^{*}-\Theta_{\mu_0}^{-1}   F(\bfw^{0};T_0) \|&~~(\text{by}~\eqref{dkt})\\
& {\leq} & \|\Theta_{\mu_0} (\bfw^{0}-\bfw^{*})-   F(\bfw^{0};T_0) \|&~~(\text{by}~\eqref{grad-F-w*-T0-c})\\
&= & \|\Theta_{\mu_0}  (\bfw^{0}-\bfw^{*})-  \int_0^1 \Theta(\beta)(\bfw^{0}-\bfw^{*})d\beta \| &~~(\text{by}~\eqref{mean-value}) \\
& \leq& \int_0^1 \|\Theta_{\mu_0} -\Theta(\beta) \|\|\bfw^{0}-\bfw^{*}\|d\beta \\
& =& ({\theta_*}/2) \|\bfw^{0} -\bfw^{*}\|^2+   {\rho C_*}  \|\bfw^1-\bfw^*\|\|\bfw^{0}-\bfw^{*}\| &~~(\text{by}~\eqref{lipschitz}) \\
&\leq& ({\theta_*}/2) \|\bfw^{0} -\bfw^{*}\|^2+ {\rho C_*\delta_*}  \|\bfw^1-\bfw^*\|   \\
&\leq& ({\theta_*}/2) \|\bfw^{0} -\bfw^{*}\|^2+ (c_*/2) \|\bfw^1-\bfw^*\|, 
\end{array}
\end{eqnarray*}
where $\theta_*:=L_* +2\rho C_*$ and the last inequality is from $\delta_*\leq  {c_*}/(2 \theta_*)$ by \eqref{delta-*} and
\beq\label{w0-w*-delta*}
\|\bfw^{0}-\bfw^{*}\|<\delta_*\leq  {c_*}/(2 \theta_*)<  {c_*}/({2\rho  C_*}).
\eeq
 The above chain of inequalities  suffices to the following fact
\beq\label{quadratic-chain}
\|\bfw^{1}-\bfw^{*}\|\leq  (\theta_*/c_*) \|\bfw^{0} -\bfw^{*}\|^2.
\eeq
This together with $\|\bfw^{0}-\bfw^{*}\|<\delta_*$ and \eqref{w0-w*-delta*} derives
\beq 
\|\bfw^{1}-\bfw^{*}\|  &\leq& 
   (\theta_*/c_*)  \delta_* \|\bfw^{0}-\bfw^{*} \|\leq (1/2)\|\bfw^{0}-\bfw^{*} \|< \delta_*,  \nonumber
 \eeq
which means $\bfw^1\in N(\bfw^*,\delta_*)$. In addition, $\mu_1\leq\mu_0\leq c_*/2$ by  \eqref{mu-k}. Hence, replacing $T_0 $ by $T_1$, the same reasoning allows us to show that $\bfd^{1}$ is well defined and $$\|\bfw^{2}-\bfw^{*}\|  \leq (\theta_*/c_*)   \|\bfw^{1}-\bfw^{*} \|^2 .$$ By the induction, we can conclude that $\bfw^k\in N(\bfw^*,\delta_*)$, $\bfd^{k}$ is well defined and 
\beq\label{quadratic-rate}
\hspace{10mm}\|\bfw^{k+1}-\bfw^{*}\|  &\leq& (\theta_*/c_*) \|\bfw^{k}-\bfw^{*} \|^2, \\
\label{quadratic-rate-1}&\leq& (\theta_*/c_*)  \|\bfw^{k}-\bfw^{*} \|\delta_* \leq (1/2) \|\bfw^{k}-\bfw^{*} \|.\hspace{.2cm}(\text{by}~\eqref{w0-w*-delta*})
\eeq
Therefore, \eqref{quadratic-rate} claims b). The conclusion of a) can be made by \eqref{quadratic-rate-1}  that   $$\bfw^{k}\rightarrow\bfw^{*},~~ \bfd^k=\bfw^{k+1}-\bfw^{k}=\bfw^{k+1}-\bfw^{*}+\bfw^{*}-\bfw^{k}\rightarrow0.$$ 

c)  The  above  proof shows $\bfw^k\in N(\bfw^*,\delta_*)$ and hence \eqref{gw*-0} results in
\beq\label{wk-in-N}  F(\bfw^{*};T_k){=}0,\eeq
where $T_k=\S_k\cup\E_k^o$.
By letting $\bfw^{k}_\beta= \bfw^{*} + \beta(\bfw^{k}-\bfw^{*}),$ where $\beta\in[0,1]$, we have $\bfw^k_\beta\in N(\bfw^*,\delta_*)$. To show \eqref{bd-jacobian-F-w-T} in \cref{lemma-neighbour-2}, we verified the lower and upper bounds by \eqref{lower-bd-FF} and \eqref{upper-bd-FF}. Similarly, we can prove these bounds hold for $\nabla F (\bfw^{k}_\beta;T_k)$. (In fact, since $\bfw^k_\beta\in N(\bfw^*,\delta_*)\subseteq N(\bfw^*,\delta_2^*)$ by $\delta_*\leq \delta_2^*$, one just needs to set $\mu=0$ and $\bfw= \bfw^{k}_\beta$ in  \eqref{lower-bd-FF} and \eqref{upper-bd-FF}. Therefore,
\beq\label{C-F-w-beta-c}
C_*  \geq \|\nabla F (\bfw^{k}_\beta;T_k)\|\geq\sigma_{\min}( \nabla F (\bfw^{k}_\beta;T_k)) \geq  c_*, 
\eeq
Again, the function $F(\cdot,T_k)$ is differentiable for the fixed $T_k$, so the Mean-value theorem states that there is a $\beta_0\in(0,1)$ satisfying
\beq\label{FkTk}
\|F(\bfw^{k},T_k)\|&=&\|F(\bfw^{*};T_k)+  \nabla F (\bfw^{k}_{\beta_0};T_k) (\bfw^{k}-\bfw^{*})\|\nonumber\\
&=&\| \nabla F (\bfw^{k}_{\beta_0};T_k) (\bfw^{k}-\bfw^{*}) \|\hspace{1.7cm}(\text{by}~\eqref{wk-in-N})\nonumber\\
&\in&  [~c_*\|\bfw^{k}-\bfw^{*} \|, C_*\|\bfw^{k}-\bfw^{*} \|~], \hspace{0.8cm}(\text{by}~\eqref{C-F-w-beta-c})
\eeq
This contributes to 
\allowdisplaybreaks
\begin{eqnarray*}\arraycolsep=1.4pt\def\arraystretch{1.5}
\begin{array}{rclr}
\|F(\bfw^{k};T_{k})\| \leq  C_*\|\bfw^{k}-\bfw^{*}\|  
 & {\leq} & (\theta_*C_*/c_*)   \|\bfw^{k-1}-\bfw^{*} \|^2 &(\text{by}~\eqref{quadratic-rate}) \\
 & {\leq}& (\theta_*C_*/c_*^{3})  \|F(\bfw^{k-1};T_{k-1})\|^2&(\text{by}~\eqref{FkTk})\\
 &{\leq}& (\theta_*C_*^3/c_*^{3})      \|\bfw^{k-1}-\bfw^{*} \|^2&(\text{by}~\eqref{FkTk})\\
& {\leq}& (\theta_*C_*^3/c_*^{3})  2^{-2}  \|\bfw^{k-2}-\bfw^{*} \|^2&~~(\text{by}~\eqref{quadratic-rate-1})\\
    &\vdots&\\
 & \leq& (\theta_*C_*^3/c_*^{3})   2^{2-2k} \|\bfw^{0}-\bfw^{*} \|^2,&(\text{by}~\eqref{quadratic-rate-1})
 \end{array}  \end{eqnarray*}
where the third inequality yields the first conclusion in c). This also enable to verify that $\|F(\bfw^{k};T_k)\|$ $< {\epsilon}$ if $k$ satisfies \eqref{k-tol}.
%$$k\geq  \lceil \log_2 (2 \sqrt{\theta_* (C_* /c_*)^3}\|\bfw^{0}-\bfw^{*} \| )-\log_2(\sqrt{\epsilon}) \rceil.$$ 
The whole proof is completed.
\end{proof}

