\begin{eqnarray*}T&=&\S\cup\E^o=\S_*\cup(\S\setminus \S_*)\cup\E^o,\\
 \overline T&=&\O\cup(\E\setminus\E^o)=\O_*\cup(\O\setminus \O_*)\cup(\E\setminus\E^o),
 \end{eqnarray*}
imply $\bfy^*_{ T} =0$ and $\bfz^*_{\overline T}=0$. 
