&=& \{i\in\N_m: y_i^*=0, z_i^*=0 \}, &~~(\text{by}~\eqref{yz-tau-lambda})\\
\E_*\setminus\E^o_*&=& \{i\in\N_m: y_i^*\neq0, y_i^*+\tau z_i^* = \sqrt{2\tau\lambda } \}&~~(\text{by} ~\eqref{p-stationary-T})\\
 &=& \{i\in\N_m: y_i^* = \sqrt{2\tau\lambda} \}&~~(\text{by}~\eqref{sta-eq-1-*-z})\\
&=&\emptyset, &~~(\text{by}~\eqref{yz-tau-lambda})
 \end{array}\end{eqnarray*}}
These facts lead to
\begin{eqnarray}\label{E*0}
\E_*=\E^o_*\cup(\E_*\setminus\E^o_*)=\E^o_*
=\Big\{i\in\N_m: y_i^*= z_i^*=0\Big\},
\end{eqnarray}
which yields the following relations
\begin{eqnarray}\label{TSETO}
\Gamma_*=\S_*\cup \E_*^o=\S_*\cup \E_*,~~~~\overline \Gamma_*= \O_*. 
\end{eqnarray}   
 {For a sufficiently small $\delta_1^*$, any $\bfw\in N(\bfw^*,\delta_1^*)$ satisfies,
\allowdisplaybreaks\begin{eqnarray}\label{hz-h*z*}
&&  {| y_i +\tau z_i - y_i^* -\tau z^*_i |\leq c\delta_1^*},~~\forall~i\in\N_m,   
\end{eqnarray} 
 {where $c>0$ is a constant relied on $A$ and $\tau$.} The definitions of $\S$ and $\S_*$  in \eqref{p-stationary-T} mean that, for any $i\in\S$ or $i\in\S_*$,
\begin{eqnarray} \label{facts-S}
\arraycolsep=1.4pt\def\arraystretch{1.5}
\begin{array}{rcll}
 y_i+\tau z_i\in (0, \sqrt{2\tau\lambda})~~ &\Longleftrightarrow&~~  |y_i+\tau z_i-\sqrt{\tau\lambda/2} |< \sqrt{\tau\lambda/2},\\
y_i^*+\tau z_i^*\in (0, \sqrt{2\tau\lambda})~~ &\Longleftrightarrow&~~  |y_i^*+\tau z_i^*-\sqrt{\tau\lambda/2} |< \sqrt{\tau\lambda/2}.
\end{array}
\end{eqnarray} 
Using this fact, if $\S_* \nsubseteq \S$, then there is an $i\in \S_*$ but $i\notin\S$ such that
\allowdisplaybreaks
\begin{eqnarray*}  
\arraycolsep=1.4pt\def\arraystretch{1.5}
\begin{array}{rcll}
|y_i +\tau z_i - y_i^* -\tau z^*_i|
&=&|y_i+\tau z_i-\sqrt{\tau\lambda/2}  - y_i^*-\tau z^*_i+\sqrt{\tau\lambda/2}|\nonumber\\
&\geq&   \sqrt{\tau\lambda/2} -|y_i^*+\tau z^*_i-\sqrt{\tau\lambda/2}| ~~~~ (\text{by}~i\notin\S~\text{and}~\eqref{facts-S})\\
  &\geq&   \sqrt{\tau\lambda/2} -\max_{i\in\S_*} |y_i^*+\tau z^*_i-\sqrt{\tau\lambda/2}| =:\delta_s\\
