\bfy^*_{\S\setminus \S_*} &=&0, &~~(\text{by}~ \S\setminus \S_*\subseteq\E_*~\text{from}~\eqref{SS*E*}~\text{and}~\eqref{E*0})\\
\bfy^*_{\E^o} &=&0,&~~(\text{by}~ \E^o\subseteq\E\subseteq\E_*~\text{from}~\eqref{SSOOEE}~\text{and}~\eqref{E*0})\\
\bfz^*_{ \O_*}  &=&0, &~~(\text{by}~\O_*\subseteq \overline \Gamma_*~\text{and}~\eqref{sta-eq-1-*})\\
\bfz^*_{\O\setminus \O_*} &=&0, &~~(\text{by}~ \O\setminus \O_*\subseteq\E_*~\text{from}~\eqref{SS*E*}~\text{and}~\eqref{E*0})\\
\bfz^*_{\E\setminus\E^o} &=&0.&~~(\text{by}~ \E\setminus\E^o\subseteq\E\subseteq\E_*~\text{from}~\eqref{SSOOEE}~\text{and}~\eqref{E*0})
\end{array}
\end{eqnarray*}
These conditions combining with
\begin{eqnarray*}T&=&\S\cup\E^o=\S_*\cup(\S\setminus \S_*)\cup\E^o,\\
