C_*&:=&2\max\{1, \|H(\Gamma_*)\|\} ,~~~~ c_* := 0.5{\min\{1,\min_{\Gamma\subseteq\Gamma_*}\sigma_{\min}(H(\Gamma))\}}, \\
\label{H*}\delta_2^* &:=& \min\left\{\delta_1^*,   \frac{c_*}{ 2L_*}     \right\},~~~~H(\Gamma):=\left[  
     \begin{array}{ccc}
    \nabla^2 f(\bfx^*)& A^\top_{\Gamma}\\
     A_{\Gamma}&0
     \end{array}
     \right]. 
\end{eqnarray}
\end{lemma}

\begin{proof}  
Since  $\nabla^2 f(\bfx^*)$ is  {positive definite} and $A_{\Gamma_*}$ is full row rank by \cref{ass}, $A_\Gamma$ is full row rank for any $ \Gamma \subseteq   \Gamma_*$ and thus $H(\Gamma)$ is non-singular. 
We have $\sigma_{\min}(H(\Gamma)) > 0$ for any 
$ \Gamma \subseteq   \Gamma_*$ 
and  $c_*>0$. 
Now we build the bounds of $\nabla F_{\mu}(\bfw;T)$. 
For any given two matrices $D'$ and $D$, we have the first fact
\begin{eqnarray} \label{lower-bd-HH}
 \|D'-D\|
&\geq& \max_{i}|\sigma_i(D')-\sigma_i(D )|   \geq |\sigma_{i_0}( D')-\sigma_{i_0}(D)|\nonumber\\
&\geq& \sigma_{i_0}(D')-\sigma_{\min}(D) \geq \sigma_{\min}(D')-\sigma_{\min}(D), 
\end{eqnarray}
where the first inequality is from \cite[Reminder (2), on Page 76]{lutkepohl1996handbook} and  $i_0$ satisfies that $\sigma_{i_0}(D)=\sigma_{\min}(D)$.  Recall that
 \begin{eqnarray*}
 \label{FH*-FG}H(\Gamma)\overset{\eqref{H*}}{=}\left[  
     \begin{array}{ccc}
    \nabla^2 f(\bfx^*)& A^\top_{\Gamma }\\
     A_{\Gamma }&0
     \end{array}
     \right],~~~~ \nabla F(\bfw^*;T) =\left[  
     \begin{array}{cc}
    H(T)&0\\
     0&I  
     \end{array}
     \right].
    \end{eqnarray*}
For any $\bfw\in N(\bfw^*,\delta_2^*)$ and $\delta_2^*\leq\delta_1^*$,   \cref{lemma-neighbour-1} contributes to $T \subseteq   \Gamma_*$. So $H(T)$ is a submatrix of $H(\Gamma_*)$. Hence, %It follows from \cite[Theorem 1]{thompson1972principal} that the maximum  singular value of a  matrix is no less than the maximum singular value of its sub-matrix. Namely, 
\beq 
\|H(T)\| \leq \|H(\Gamma_*)\|,~~ \sigma_{\min}(H(T)) \geq \min_{\Gamma \subseteq \Gamma_*} \sigma_{\min} (H(\Gamma)),\nonumber
\eeq
where the latter is by $T \subseteq   \Gamma_*$, which gives us the second fact 
\beq\label{JJogG0}
\sigma_{\min}(\nabla F(\bfw^*;T))&=&\min\{1,\sigma_{\min}(H(T))\}\\
& \geq&\min\{1, \min_{\Gamma \subseteq \Gamma_*} \sigma_{\min} (H(\Gamma))\}=2c_*, \nonumber\\
\label{JJogG1}
\|\nabla F(\bfw^*;T)\| &=& \max\{1, \|H(T)\|\} \leq \max\{1, \|H(\Gamma_*)\|\} =C_*/2. 
\eeq
The locally Lipschitz continuity of $\nabla^2 f$  around $\bfx^*$ with $L_*$  yields the third fact,
\begin{eqnarray}
\label{HH*2}
\|\nabla F (\bfw^*;T)-\nabla F (\bfw;T)\|&=&\|\nabla^2  f (\bfx)-\nabla^2  f (\bfx^*)\|  \leq
   L_* \| \bfx -\bfx^* \| \nonumber\\
   &\leq& L_* \| \bfw -\bfw^* \| 
 \leq   L_* \delta_2^*
\leq c_*/2.   \hspace{.5cm}(\text{by}~\eqref{H*})
\end{eqnarray} 
Now these three facts allow us to derive
\allowdisplaybreaks 
\begin{eqnarray}\label{lower-bd-FF}
\arraycolsep=1.4pt\def\arraystretch{1.5}
\begin{array}{rclr}
&& \sigma_{\min}(\nabla F_{\mu}(\bfw;T))\\
 &\geq& \sigma_{\min}(\nabla F (\bfw ;T))- \|\nabla F(\bfw;T)-\nabla F_{\mu}  (\bfw;T)\| &(\text{by}~\eqref{lower-bd-HH})  \\
&=& \sigma_{\min}(\nabla F(\bfw ;T))- \mu &(\text{by}~\eqref{sta-eq-1}) \\
&\geq& \sigma_{\min}(\nabla F(\bfw^*;T))- \|\nabla F (\bfw^*;T)-\nabla F (\bfw;T)\|- \mu   &(\text{by}~\eqref{lower-bd-HH}) \\
&\geq&\sigma_{\min}(\nabla F(\bfw^*;T))- c_*/2 - \mu&(\text{by}~\eqref{HH*2}) \\
&\geq&\sigma_{\min}(\nabla F(\bfw^*;T))-  c_* &(\text{by}~\mu\leq c_*/2)   \\
&\geq&c_*. &(\text{by}~\eqref{JJogG0})  
\end{array}
\end{eqnarray}
Similarly, we also have
\allowdisplaybreaks 
\begin{eqnarray}\label{upper-bd-FF}
\arraycolsep=1.4pt\def\arraystretch{1.5}
\begin{array}{rclr}
&&\|\nabla F_{\mu}(\bfw;T)\|\\
 &\leq& \|\nabla F (\bfw ;T)\|+ \|\nabla F(\bfw;T)-\nabla F_{\mu}  (\bfw;T)\| \\
&=& \|\nabla F (\bfw ;T)\|+ \mu &(\text{by}~\eqref{sta-eq-1})\\
&\leq& \|\nabla F(\bfw^*;T)\|+ \|\nabla F (\bfw^*;T)-\nabla F (\bfw;T)\|+ \mu   &(\text{by}~\eqref{lower-bd-HH})  \\
&\leq& \|\nabla F(\bfw^*;T)\|+ c_*/2 + \mu&(\text{by}~\eqref{HH*2}) \\
&\leq& \|\nabla F(\bfw^*;T)\|+ c_* &(\text{by}~\mu\leq c_*/2)   \\
&\leq& C_*/2+c_* &(\text{by}~\eqref{JJogG1}) \\
&\leq& C_*. &(\text{by}~c_*\leq C_*/2)   
\end{array}
\end{eqnarray}
The whole proof is completed. 
\end{proof}

