&& \sigma_{\min}(\nabla F_{\mu}(\bfw;T))\\
 &\geq& \sigma_{\min}(\nabla F (\bfw ;T))- \|\nabla F(\bfw;T)-\nabla F_{\mu}  (\bfw;T)\| &(\text{by}~\eqref{lower-bd-HH})  \\
&=& \sigma_{\min}(\nabla F(\bfw ;T))- \mu &(\text{by}~\eqref{sta-eq-1}) \\
