\end{proof}

\begin{theorem}\label{quadratic-convergence} 
Let $\bfw^*$ be any {\ts} with $0<\tau<\tau_*$ of  (\ref{ell-0-1}), $\tau_*$ and $\delta_2^*, c_*, C_*$ be given by (\ref{tau-*}) and (\ref{radius-2}). Assume  \cref{ass} and \cref{ass2}. Let $\{\bfw^k\}$ be the  sequence generated by  \cref{Alg-NM01} and $0\leq\mu_{-1}\leq c_*/2$. If the initial point  satisfies $\bfw^0\in N(\bfw^*,\delta_*)$, where
\begin{eqnarray}\label{delta-*}
\delta_*:=\min\left\{\delta_2^*,~{c_*}/{(2 (L_*+2\rho C_*))}\right\},
\end{eqnarray}
 then the following results hold.
\begin{itemize}
\item[a)] The sequence $\{\bfd^k\}_{k\geq0}$ is well defined and $\lim_{k\rightarrow\infty}\bfd^k=0$. 
\item[b)] The whole sequence $\{\bfw^k\}$ converges to $\bfw^*$ quadratically, namely,
\beq
\|\bfw^{k+1}-\bfw^{*}\|  &\leq& 
  ((L_*+2\rho C_*)/c_*) \|\bfw^{k}-\bfw^{*} \|^2. \nonumber 
\eeq
\item[c)] The halting condition satisfies
\beq
\|F(\bfw^{k+1};T_{k+1})\| 
&\leq& (L_*+2\rho C_*)(C_*/c_*^{3})  \|F(\bfw^{k};T_k)\|^2  \nonumber 
\eeq
and  \Cref{Alg-NM01} reaches $\|F(\bfw^{k};T_k)\| <  \epsilon$ for a given tolerance $\epsilon>0$ when \beq\label{k-tol}
k\geq \Big\lceil \log_2\Big(2 \sqrt{(L_*+2\rho C_*)(C_*/c_*)^3  }\|\bfw^{0}-\bfw^{*} \|\Big)-\log_2(\sqrt{\epsilon})\Big\rceil.\eeq  
\end{itemize}
\end{theorem}

Let $\bfw^*$ be any {\ts} with $0<\tau<\tau_*$ of  (\ref{ell-0-1}), $\tau_*$ and $\delta_2^*, c_*, C_*$ be given by (\ref{tau-*}) and (\ref{radius-2}). Assume  \cref{ass} and \cref{ass2}. Let $\{\bfw^k\}$ be the  sequence generated by  \cref{Alg-NM01} and $0\leq\mu_{-1}\leq c_*/2$. If the initial point  satisfies $\bfw^0\in N(\bfw^*,\delta_*)$, where
\begin{eqnarray}\label{delta-*}
\delta_*:=\min\left\{\delta_2^*,~{c_*}/{(2 (L_*+2\rho C_*))}\right\},
\end{eqnarray}

\begin{proof} a) It is easily observed   
\begin{eqnarray}\label{mu-k}
0< \mu_{k} \leq \mu_{k-1}, ~k=1,2,3,\ldots, ~~~~{\rm and}~~~~ \lim_{k\rightarrow\infty}\mu_k=0.
\end{eqnarray}

The definition  in \eqref{sta-eq-1} enables us to obtain
\allowdisplaybreaks 
\begin{eqnarray*}
\arraycolsep=1.4pt\def\arraystretch{1.5}
\begin{array}{rcll}
&&\|\nabla F_{\mu_0} (\bfw^{0};T_0)- \nabla F (\bfw^{0}_\beta;T_0) \|  \\
&\leq&\|\nabla^2 f(\bfx^0)- \nabla^2 f(\bfx^0_\beta)\| + \mu_0&(\text{by}~\eqref{sta-eq-1})  \\
& \leq& L_* \|\bfx^0-\bfx^0_\beta\|+ \rho  \|F(\bfw^0;T_0)\|&(\text{by}~\eqref{update-mu}) \\ 
& \leq& L_* \|\bfw^0-\bfw^0_\beta\|+ \rho \|\nabla F_{\mu_0} (\bfw^{0};T_0)\| \|\bfd^0\|&(\text{by}~\eqref{newton-dir-0}) \\ 
& \leq& L_* \|\bfw^0-\bfw^0_\beta\|+ \rho C_* \|\bfw^1-\bfw^0\|&(\text{by}~\eqref{grad-F-w*-T0-c}) \\ 
& \leq& L_*(1-\beta)\|\bfw^0-\bfw^*\|+ \rho C_* (\|\bfw^1-\bfw^*\|+\|\bfw^0-\bfw^*\|) &(\text{by}~\eqref{w0-beta-w*})  \\ 
& =& (L_*(1-\beta)+\rho C_*)\|\bfw^0-\bfw^*\|+ \rho C_* \|\bfw^1-\bfw^*\|.
\end{array} \end{eqnarray*}
Denote $\Theta_{\mu_0}:=\nabla F_{\mu_0} (\bfw^{0};T_0)$ and $\Theta(\beta):= \nabla F (\bfw^{0}_\beta;T_0)$.  The above condition yields
  \beq\label{lipschitz}
\arraycolsep=1.4pt\def\arraystretch{1.5}
\begin{array}{rcll}
 \int_0^1 \|\Theta_{\mu_0}  - \Theta(\beta)\|d\beta
\leq (L_*/2+\rho C_*)\|\bfw^0-\bfw^*\|+ \rho C_* \|\bfw^1-\bfw^*\|.
\end{array} \eeq

For the fixed $T_0$, the function $F(\cdot,T_0)$ is differentiable, which by \eqref{F-w*-T0-0} derives
\beq\label{mean-value}
\arraycolsep=1.4pt\def\arraystretch{1.5}
\begin{array}{rcll}
F (\bfw^{0};T_0)=F (\bfw^{*};T_0)+\int_0^1 \Theta(\beta)(\bfw^{0}-\bfw^{*})d\beta=\int_0^1 \Theta(\beta) (\bfw^{0}-\bfw^{*})d\beta.
\end{array}\eeq

Now the following chain of inequalities holds.
\begin{eqnarray*}
\arraycolsep=1.4pt\def\arraystretch{1.5}
\begin{array}{rcll}
c_*\|\bfw^{1}-\bfw^{*}\| &=& c_*\|\bfw^{0}+\bfd^{0}-\bfw^{*}\|\\
& {=} &c_*\|\bfw^{0}-\bfw^{*}-\Theta_{\mu_0}^{-1}   F(\bfw^{0};T_0) \|&~~(\text{by}~\eqref{dkt})\\
& {\leq} & \|\Theta_{\mu_0} (\bfw^{0}-\bfw^{*})-   F(\bfw^{0};T_0) \|&~~(\text{by}~\eqref{grad-F-w*-T0-c})\\
&= & \|\Theta_{\mu_0}  (\bfw^{0}-\bfw^{*})-  \int_0^1 \Theta(\beta)(\bfw^{0}-\bfw^{*})d\beta \| &~~(\text{by}~\eqref{mean-value}) \\
& \leq& \int_0^1 \|\Theta_{\mu_0} -\Theta(\beta) \|\|\bfw^{0}-\bfw^{*}\|d\beta \\
& =& ({\theta_*}/2) \|\bfw^{0} -\bfw^{*}\|^2+   {\rho C_*}  \|\bfw^1-\bfw^*\|\|\bfw^{0}-\bfw^{*}\| &~~(\text{by}~\eqref{lipschitz}) \\
&\leq& ({\theta_*}/2) \|\bfw^{0} -\bfw^{*}\|^2+ {\rho C_*\delta_*}  \|\bfw^1-\bfw^*\|   \\
&\leq& ({\theta_*}/2) \|\bfw^{0} -\bfw^{*}\|^2+ (c_*/2) \|\bfw^1-\bfw^*\|, 
\end{array}
\end{eqnarray*}
where $\theta_*:=L_* +2\rho C_*$ and the last inequality is from $\delta_*\leq  {c_*}/(2 \theta_*)$ by \eqref{delta-*} and
\beq\label{w0-w*-delta*}
\|\bfw^{0}-\bfw^{*}\|<\delta_*\leq  {c_*}/(2 \theta_*)<  {c_*}/({2\rho  C_*}).
\eeq
